changeSet.sql:
ALTER TABLE financial.payments
    ALTER COLUMN id_wallet DROP NOT NULL;
ALTER TABLE financial.payments
    ADD COLUMN id_card bigint;
ALTER TABLE financial.payments
    ADD CONSTRAINT fk_cards_on_payments FOREIGN KEY (id_card) REFERENCES registration.cards (id);
CREATE INDEX ix_payments_on_card ON financial.payments (id_card);
ALTER TABLE financial.payments
    DROP CONSTRAINT ck_payments_on_method;
ALTER TABLE financial.payments
    ADD CONSTRAINT ck_payments_on_method CHECK (method IN ('WALLET', 'CARD'));
ALTER TABLE financial.payments
    ADD CONSTRAINT ck_payments_on_instrument CHECK (
        (method = 'WALLET' AND id_wallet IS NOT NULL AND id_card IS NULL)
        OR (method = 'CARD' AND id_card IS NOT NULL AND id_wallet IS NULL)
    );

rollback.sql:
DELETE FROM financial.payments WHERE method = 'CARD';
ALTER TABLE financial.payments
    DROP CONSTRAINT ck_payments_on_instrument;
ALTER TABLE financial.payments
    DROP CONSTRAINT ck_payments_on_method;
ALTER TABLE financial.payments
    ADD CONSTRAINT ck_payments_on_method CHECK (method IN ('WALLET'));
DROP INDEX financial.ix_payments_on_card;
ALTER TABLE financial.payments
    DROP CONSTRAINT fk_cards_on_payments;
ALTER TABLE financial.payments
    DROP COLUMN id_card;
ALTER TABLE financial.payments
    ALTER COLUMN id_wallet SET NOT NULL;
